{"file_path":"tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_includes_none_in_denominator():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_equally():
    groups = {"large": [{"converted": False}] * 3, "small": [{"converted": True}], "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 2), (2, 5), (10, 9)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([4, 3, 2], days) == expected


def test_parse_session_log_skips_non_records_and_parses_flags():
    events = parse_session_log(["", " \t\n", "  # comment,with,commas", " a , 1 , 1 ", " b , 2 , 0 ", " c , 3 , "])
    assert [(e["id"], e["day"]) for e in events] == [("a", 1), ("b", 2), ("c", 3)]
    assert events[0]["converted"] is True
    assert events[1]["converted"] is False
    assert events[2]["converted"] is None


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,not-a-day,1"])
def test_parse_session_log_error_counts_skipped_lines(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_session_log(["", "  # comment", "a,1,1", bad_line])


def test_dedupe_sessions_keeps_last_record_and_sorts_by_day_then_id():
    events = parse_session_log(["b,1,1", "c,3,1", "b,2,0", "a,2,1", "d,1,"])
    assert dedupe_sessions(events) == [events[4], events[3], events[2], events[1]]


def test_daily_conversion_counts_includes_bounds_and_fills_gaps():
    events = parse_session_log(["a,1,1", "b,2,1", "c,2,1", "d,3,0", "e,3,", "f,4,1", "g,5,1"])
    assert daily_conversion_counts(events, 2, 4) == [2, 0, 1]
    assert daily_conversion_counts(events, 4, 2) == []


def test_campaign_summary_uses_pooled_rate_and_calendar_window():
    groups = {"a": parse_session_log(["a,1,1", "b,2,1"]), "b": parse_session_log(["c,4,0"]), "empty": []}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 3)["recent"] == 1
    assert campaign_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [{"converted": True}], "low": [{"converted": None}], "a": [{"converted": True}], "empty": []}
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 5) == ["a", "z", "low"]


def test_conversion_rate_by_group_sorts_names_and_marks_empty_groups():
    groups = {"z": [{"converted": True}], "a": [], "b": [{"converted": None}]}
    assert list(conversion_rate_by_group(groups).items()) == [("a", None), ("b", 0.0), ("z", 1.0)]


@pytest.mark.parametrize("counts, expected", [([1, 2, 0, 3, -1, 4], 2), ([0, -1], 0), ([], 0)])
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected
